import {rotatePoint} from './chapter-shoes.js?v=motion-v56';
import {rasterSurface,putSurface} from './raster-surface.js?v=motion-v56';
let buffer,tint;
const rgb=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));
export function sealedShoeMesh(color='#343335',spikeLength=.22){const faces=[],N=34,M=24,quad=(p,color,material='leather')=>faces.push({p,color,material}),shape=x=>{const t=(x+1.4)/2.8,w=Math.max(.012,Math.sin(Math.PI*t)**.42*(.4+.16*t)),h=.43-.22*t+.06*Math.exp(-(((t-.28)/.2)**2));return {w,h}},top=(x,z)=>{const a=shape(x);return -.12+a.h*Math.sqrt(Math.max(0,1-(z/a.w)**2))},point=(i,j)=>{const x=-1.4+i/N*2.8,a=j/M*Math.PI,p=shape(x);return [x,-.12+p.h*Math.sin(a),p.w*Math.cos(a)]};
for(let i=0;i<N;i++)for(let j=0;j<M;j++)quad([point(i,j),point(i+1,j),point(i+1,j+1),point(i,j+1)],color);
for(let i=0;i<N;i++){const x=-1.4+i/N*2.8,X=-1.4+(i+1)/N*2.8,a=shape(x),b=shape(X);for(const side of [-1,1])quad([[x,-.12,side*a.w],[X,-.12,side*b.w],[X,-.26,side*b.w],[x,-.26,side*a.w]],'#19191b','rubber');quad([[x,-.26,-a.w],[X,-.26,-b.w],[X,-.26,b.w],[x,-.26,a.w]],'#151517','rubber');}
for(const i of [0,N]){const x=-1.4+i/N*2.8,p=shape(x);for(let j=0;j<M;j++)quad([[x,-.12,0],point(i,j),point(i,j+1)],color);quad([[x,-.12,-p.w],[x,-.12,p.w],[x,-.26,p.w],[x,-.26,-p.w]],'#19191b','rubber');}
for(let j=0;j<24;j++){const a=j/24*Math.PI*2,b=(j+1)/24*Math.PI*2,p=a=>{const x=-.94+Math.cos(a)*.24,z=Math.sin(a)*.18;return [x,top(x,z)+.006,z]};quad([[-.94,top(-.94,0)+.007,0],p(a),p(b)],'#111113','opening');}
for(let i=0;i<6;i++)for(const side of [-1,1])for(let j=0;j<12;j++){const x=-.55+i*.13,point=t=>{const X=x+.08*t,Z=.16*side*(1-2*t);return [X,top(X,Z)+.014,Z]},p=point(j/12),q=point((j+1)/12);quad([p,[p[0]+.022,p[1]+.004,p[2]], [q[0]+.022,q[1]+.004,q[2]],q],'#131315','lace');}
if(spikeLength>0)for(const x of [-.55,.35,.9])for(const z of [-.18,.18])for(let j=0;j<10;j++){const a=j/10*Math.PI*2,b=(j+1)/10*Math.PI*2;quad([[x+Math.cos(a)*.035,-.26,z+Math.sin(a)*.035],[x+Math.cos(b)*.035,-.26,z+Math.sin(b)*.035],[x,-.26-spikeLength,z]],'#d4d6d8','metal');}return faces;}
export function solidShoeTriangles(o={}){const mesh=sealedShoeMesh(o.color||'#343335',o.spikeLength??.22),triangles=[],pose={yaw:o.yaw??-90,pitch:o.pitch??12,roll:o.roll??0},size=o.size??650,project=([x,y,z])=>{const k=6/(6-z*.17);return [(o.x??480)+x*size/3*k,(o.y??270)-y*size/3*k,z]};for(const face of mesh){const v=face.p.map(p=>rotatePoint(rotatePoint(p,{yaw:pose.yaw}),{pitch:pose.pitch,roll:pose.roll}));for(let i=1;i<v.length-1;i++){const a=v[0],b=v[i],c=v[i+1],ab=b.map((x,k)=>x-a[k]),ac=c.map((x,k)=>x-a[k]),n=[ab[1]*ac[2]-ab[2]*ac[1],ab[2]*ac[0]-ab[0]*ac[2],ab[0]*ac[1]-ab[1]*ac[0]],len=Math.hypot(...n)||1,light=.48+.5*Math.abs((n[0]*-.25+n[1]*.7+n[2]*.65)/len),metal=face.material==='metal';let color=rgb(face.color);if(!metal&&face.material==='rubber')color=[24,24,25];triangles.push({points:[project(a),project(b),project(c)].map((p,j)=>[...p,(face.p[[0,i,i+1][j]][0]+1.4)/2.8,(face.p[[0,i,i+1][j]][2]+.6)/1.2]),color,grain:face.material==='leather'?.25:0,shade:light*(o.brightness??1)});}}return triangles;}
export function paintSolidShoe(c,o={}){buffer||=Object.assign(document.createElement('canvas'),{width:960,height:540});tint||=Object.assign(document.createElement('canvas'),{width:960,height:540});putSurface(buffer,rasterSurface(960,540,solidShoeTriangles(o)));if(o.outlineWidth>0){const t=tint.getContext('2d');t.clearRect(0,0,960,540);t.globalCompositeOperation='source-over';t.drawImage(buffer,0,0);t.globalCompositeOperation='source-in';t.fillStyle=o.outline||'#7185aa';t.fillRect(0,0,960,540);t.globalCompositeOperation='source-over';for(let i=0;i<24;i++){const a=i/24*Math.PI*2;c.drawImage(tint,Math.cos(a)*o.outlineWidth,Math.sin(a)*o.outlineWidth)}}c.drawImage(buffer,0,0);}
